  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Approves a pending IPO application, updates its status to APPROVAL, and sends notification emails to both the customer and the company. Only pending applications can be approved, and the customer must still be eligible for IPO.
   * Algorithm:
   *   1. If status is not PENDING, return false.
   *   2. If customer.isEligibleForIPO() returns false, return false.
   *   3. Set status = APPROVAL.
   *   4. Call sendEmailsToCustomerAndCompany().
   *   5. Return true.
   * Related Features: Application.status, customer.isEligibleForIPO(), sendEmailsToCustomerAndCompany()
   * Related Classes: Customer, Company, Email
   * Input: None (operates on the current Application instance)
   * Output: boolean - true if approval succeeds, false otherwise.
   * Pre-condition: The application exists and is in PENDING status. The customer must be eligible for IPO (isEligibleForIPO() returns true).
   * Post-condition: If successful, status is APPROVAL, and two emails are sent (one to customer, one to company). If failed, status remains unchanged and no emails are sent.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public boolean approve()
  {
    if (getStatus() != ApplicationStatus.PENDING) {
      return false;
    }
    if (!getCustomer().isEligibleForIPO()) {
      return false;
    }
    setStatus(ApplicationStatus.APPROVAL);
    sendEmailsToCustomerAndCompany();
    return true;
  }

