  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Sends two information emails: one to the customer and one to the company, notifying them about the successful approval of the IPO application.
   * Algorithm:
   *   1. Create an Email object for the customer:
   *      - receiver = customer.email
   *      - content = Email.createEmailContent(company, share, customer, amountOfMoney)
   *      - Add to Application.emails list.
   *   2. Create an Email object for the company:
   *      - receiver = company.email
   *      - content = Email.createEmailContent(company, share, customer, amountOfMoney) (or a different content as needed)
   *      - Add to Application.emails list.
   *   3. Optionally, send the emails (in a real system, this would trigger an email sending service; here we assume adding to the list represents sending).
   * Related Features: Application.customer, Application.company, Application.amountOfMoney, Application.share, Application.emails, Email::createEmailContent
   * Related Classes: Customer, Company, Email
   * Input: None (operates on the current Application instance)
   * Output: void
   * Pre-condition: The application is approved (status = APPROVAL), and customer and company objects are non-null.
   * Post-condition: Two Email objects are added to the emails list, one for the customer and one for the company.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void sendEmailsToCustomerAndCompany()
  {
    // Create email for customer
    Email customerEmail = IpoFactory.eINSTANCE.createEmail();
    customerEmail.setReceiver(getCustomer().getEmail());
    customerEmail.setContent(customerEmail.createEmailContent(getCompany(), getShare(), getCustomer(), getAmountOfMoney()));
    getEmails().add(customerEmail);

    // Create email for company
    Email companyEmail = IpoFactory.eINSTANCE.createEmail();
    companyEmail.setReceiver(getCompany().getEmail());
    companyEmail.setContent(companyEmail.createEmailContent(getCompany(), getShare(), getCustomer(), getAmountOfMoney()));
    getEmails().add(companyEmail);
  }

  /**
   * <!-- begin-user-doc -->
   * <!-- end-user-doc -->
   * <!-- begin-model-doc -->
   * Summary: Sends a rejection email to the customer with detailed information about the rejected application, including customer personal details, company name, shares, and paid amount.
   * Algorithm:
   *   1. Create an Email object for the customer:
   *      - receiver = customer.email
   *      - content = "Dear " + customer.name + " " + customer.surname + ",\n\nYour IPO application for " + company.name + " has been rejected.\n\nDetails:\n- Name: " + customer.name + "\n- Surname: " + customer.surname + "\n- Email: " + customer.email + "\n- Telephone: " + customer.telephone + "\n- Company: " + company.name + "\n- Shares: " + share + "\n- Paid Amount: " + amountOfMoney + "\n\nThank you."
   *      - Add to Application.emails list.
   *   2. Optionally, send the email (same assumption as above).
   * Related Features: Application.customer, Application.company, Application.amountOfMoney, Application.share, Application.emails
   * Related Classes: Customer, Company, Email
   * Input: None (operates on the current Application instance)
   * Output: void
   * Pre-condition: The application is rejected (status = REJECTED), and customer and company objects are non-null.
   * Post-condition: One Email object is added to the emails list for the customer with the rejection details.
   * <!-- end-model-doc -->
   * @model annotation="http://www.ustb.edu.cn/sei/mde/EnhancedCodeGen generated='true'"
   * @generated NOT
   */
  public void sendRejectionEmail()
  {
    Email rejectionEmail = IpoFactory.eINSTANCE.createEmail();
    rejectionEmail.setReceiver(getCustomer().getEmail());
    
    Customer cust = getCustomer();
    Company comp = getCompany();
    
    String content = "Dear " + cust.getName() + " " + cust.getSurname() + ",\n\n" +
                     "Your IPO application for " + comp.getName() + " has been rejected.\n\n" +
                     "Details:\n" +
                     "- Name: " + cust.getName() + "\n" +
                     "- Surname: " + cust.getSurname() + "\n" +
                     "- Email: " + cust.getEmail() + "\n" +
                     "- Telephone: " + cust.getTelephone() + "\n" +
                     "- Company: " + comp.getName() + "\n" +
                     "- Shares: " + getShare() + "\n" +
                     "- Paid Amount: " + getAmountOfMoney() + "\n\n" +
                     "Thank you.";
    
    rejectionEmail.setContent(content);
    getEmails().add(rejectionEmail);
  }

